window.products.push({"id":1137084,"name":"simplehuman 14 oz. Sensor Pump, Black (Discontinued)","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/31ZMoeSsSNL._AC_.jpg","description":"Leave it to simplehuman to revolutionize the way we wash our hands. The sensor soap pump dispenses soap touch-free to help avoid cross-contamination. Simply place your hand under the sensor to dispense soap automatically. An optional LED light timer blinks for 20 seconds to indicate how long to lather for germ-free hands. Four volume settings allow the pump to dispense preset amounts of soap or lotion. Operates on 4 AA batteries (not included).","images":["https://m.media-amazon.com/images/I/31ZMoeSsSNL._AC_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"simplehuman","source_asin":"B000Q6L7JQ","category_path":"Home & Kitchen"},"sku":"BM-1137084","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B000Q6L7JQ","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B000Q6L7JQ","price_pending":true,"merchant_ready":false});
